+package cache
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+func TestSimpleCacheAddAndGetTypedValue(t *testing.T) {
+	c := NewSimpleCache[int]()
+	if err := c.Add("answer", 42); err != nil {
+		t.Fatal(err)
+	}
+	got, err := c.Get("answer")
+	if err != nil || got != 42 {
+		t.Fatalf("Get(answer) = %d, %v; want 42, nil", got, err)
+	}
+	missing, err := c.Get("missing")
+	if err == nil || missing != 0 {
+		t.Fatalf("Get(missing) = %d, %v; want zero value and error", missing, err)
+	}
+}
+
+func TestSimpleCacheTTLDoesNotExtendOnHit(t *testing.T) {
+	c := NewSimpleCache[string]()
+	if err := c.AddWithTTL("short", "value", 300*time.Millisecond); err != nil {
+		t.Fatal(err)
+	}
+	if got, err := c.Get("short"); err != nil || got != "value" {
+		t.Fatalf("early Get = %q, %v", got, err)
+	}
+	time.Sleep(100 * time.Millisecond)
+	if got, err := c.Get("short"); err != nil || got != "value" {
+		t.Fatalf("middle Get = %q, %v", got, err)
+	}
+	time.Sleep(250 * time.Millisecond)
+	if got, err := c.Get("short"); err == nil || got != "" {
+		t.Fatalf("expired Get = %q, %v; want zero value and error", got, err)
+	}
+	for _, key := range c.Keys() {
+		if key == "short" {
+			t.Fatal("Keys includes expired entry")
+		}
+	}
+}
+
+func TestSimpleCacheLoaderStoresValueAndUsesCacheOnHit(t *testing.T) {
+	c := NewSimpleCache[string]()
+	calls := 0
+	loader := func(key string) (string, time.Duration, error) {
+		calls++
+		return key + "-loaded", time.Minute, nil
+	}
+	for i := 0; i < 2; i++ {
+		got, err := c.GetWithLoader("item", loader)
+		if err != nil || got != "item-loaded" {
+			t.Fatalf("GetWithLoader = %q, %v", got, err)
+		}
+	}
+	if calls != 1 {
+		t.Fatalf("loader called %d times; want once", calls)
+	}
+	if keys := c.Keys(); len(keys) != 1 || keys[0] != "item" {
+		t.Fatalf("Keys = %v; want [item]", keys)
+	}
+}
+
+func TestSimpleCacheLoaderErrorIsReturnedWithoutCaching(t *testing.T) {
+	c := NewSimpleCache[int]()
+	want := errors.New("load failed")
+	got, err := c.GetWithLoader("item", func(string) (int, time.Duration, error) {
+		return 7, time.Minute, want
+	})
+	if got != 0 || err != want {
+		t.Fatalf("GetWithLoader = %d, %v; want zero and original error", got, err)
+	}
+	if keys := c.Keys(); len(keys) != 0 {
+		t.Fatalf("Keys = %v; want empty", keys)
+	}
+}
+
+func TestSimpleCacheWithSizeLimitEvictsOldestEntry(t *testing.T) {
+	c := newSimpleCacheWithSizeLimit[string](2)
+	for _, key := range []string{"first", "second", "third"} {
+		if err := c.Add(key, key); err != nil {
+			t.Fatal(err)
+		}
+	}
+	if _, err := c.Get("first"); err == nil {
+		t.Fatal("oldest entry still present after size limit")
+	}
+	for _, key := range []string{"second", "third"} {
+		if got, err := c.Get(key); err != nil || got != key {
+			t.Fatalf("Get(%q) = %q, %v", key, got, err)
+		}
+	}
+}
+
+func TestSimpleCacheStoresNilInterfaceValue(t *testing.T) {
+	c := NewSimpleCache[any]()
+	if err := c.Add("nil", nil); err != nil {
+		t.Fatal(err)
+	}
+	got, err := c.Get("nil")
+	if err != nil || got != nil {
+		t.Fatalf("Get(nil) = %v, %v; want nil value without error", got, err)
+	}
+}

