+func TestSimpleCacheAddAndGetTypedValue(t *testing.T) {
+	c := NewSimpleCache[int]()
+	if err := c.Add("answer", 42); err != nil {
+		t.Fatal(err)
+	}
+	got, err := c.Get("answer")
+	if err != nil || got != 42 {
+		t.Fatalf("Get(answer) = %d, %v; want 42, nil", got, err)
+	}
+	missing, err := c.Get("missing")
+	if err == nil || missing != 0 {
+		t.Fatalf("Get(missing) = %d, %v; want zero value and error", missing, err)
+	}
+}
+
+func TestSimpleCacheTTLDoesNotExtendOnHit(t *testing.T) {
+	c := NewSimpleCache[string]()
+	if err := c.AddWithTTL("short", "value", 300*time.Millisecond); err != nil {
+		t.Fatal(err)
+	}
+	if got, err := c.Get("short"); err != nil || got != "value" {
+		t.Fatalf("early Get = %q, %v", got, err)
+	}
+	time.Sleep(100 * time.Millisecond)
+	if got, err := c.Get("short"); err != nil || got != "value" {
+		t.Fatalf("middle Get = %q, %v", got, err)
+	}
+	time.Sleep(250 * time.Millisecond)
+	if got, err := c.Get("short"); err == nil || got != "" {
+		t.Fatalf("expired Get = %q, %v; want zero value and error", got, err)
+	}
+	for _, key := range c.Keys() {
+		if key == "short" {
+			t.Fatal("Keys includes expired entry")
+		}
+	}
+}
