+func TestSimpleCacheLoaderStoresValueAndUsesCacheOnHit(t *testing.T) {
+	c := NewSimpleCache[string]()
+	calls := 0
+	loader := func(key string) (string, time.Duration, error) {
+		calls++
+		return key + "-loaded", time.Minute, nil
+	}
+	for i := 0; i < 2; i++ {
+		got, err := c.GetWithLoader("item", loader)
+		if err != nil || got != "item-loaded" {
+			t.Fatalf("GetWithLoader = %q, %v", got, err)
+		}
+	}
+	if calls != 1 {
